// Generated by esquadro: do not edit. Money: an exact amount, written as
// text ("19.90", never a number), and its currency (ISO 4217). Shown in the
// locale with its symbol, summed exactly by currency, and typed in a field
// that writes it as the locale does ("R$ 1.234,56").
import { add, dinero, toDecimal } from "dinero.js/bigint"
import type { Dinero } from "dinero.js/bigint"
import * as currencies from "dinero.js/bigint/currencies"
import { NumericFormat } from "react-number-format"
import { Input } from "@/components/ui/input"
import { currency as appCurrency, locale } from "../config.ts"

/** An amount and its currency, as the API writes them. */
export interface Money {
  amount: string
  currency?: string
}

/** Whether v is money as the API writes it. */
export function isMoney(v: unknown): v is Money {
  return typeof v === "object" && v !== null && typeof (v as Money).amount === "string"
}

/** The currency of an amount: its own, else the app's. */
export function currencyOf(m?: Partial<Money> | null): string {
  return m?.currency || appCurrency || "USD"
}

/** The places a currency is written with: 2 for BRL, 0 for JPY, 3 for KWD. */
export function places(code: string): number {
  try {
    return new Intl.NumberFormat("en", { style: "currency", currency: code }).resolvedOptions().maximumFractionDigits ?? 2
  } catch {
    return 2
  }
}

/** The places an amount is written with: "12.3456" has 4. */
function placesOf(amount: string): number {
  const dot = amount.indexOf(".")
  return dot < 0 ? 0 : amount.length - dot - 1
}

/**
 * An amount in the locale, with its currency: R$ 1.234,56. Exact: the
 * text is formatted as it is, never through a float, and an amount finer
 * than its currency (12.3456) keeps its places.
 */
export function formatMoney(m: unknown, options?: Intl.NumberFormatOptions): string {
  if (!isMoney(m)) return "—"
  const code = currencyOf(m)
  const digits = places(code)
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency: code,
    minimumFractionDigits: digits,
    maximumFractionDigits: Math.max(digits, Math.min(placesOf(m.amount), 4)),
    ...options,
  }).format(m.amount as unknown as number)
}

const SCALE = 4

/** An amount as dinero.js takes it: its units at four places. */
function toDinero(m: Money): Dinero<bigint> {
  const code = currencyOf(m)
  // The ISO currencies dinero.js knows; another, made from its places.
  const known = (currencies as unknown as Record<string, unknown>)[code]
  const currency = known ?? { code, base: 10n, exponent: BigInt(places(code)) }
  const [whole, fraction = ""] = m.amount.replace(/^-/, "").split(".")
  let units = BigInt(whole || "0") * 10n ** BigInt(SCALE) + BigInt((fraction + "0000").slice(0, SCALE) || "0")
  if (m.amount.startsWith("-")) units = -units
  return dinero({ amount: units, currency, scale: BigInt(SCALE) } as never)
}

/** A sum back to text: "1234.5" (no trailing zeros). */
function fromDinero(d: Dinero<bigint>): string {
  const s = toDecimal(d)
  return s.includes(".") ? s.replace(/0+$/, "").replace(/\.$/, "") : s
}

/**
 * The amounts summed exactly, one total per currency (amounts of two
 * currencies are never added up), in the order the currencies appear.
 */
export function sumMoney(values: unknown[]): Money[] {
  const totals = new Map<string, Dinero<bigint>>()
  for (const v of values) {
    if (!isMoney(v)) continue
    const code = currencyOf(v)
    const d = toDinero(v)
    const prev = totals.get(code)
    totals.set(code, prev ? add(prev, d) : d)
  }
  return [...totals].map(([currency, d]) => ({ amount: fromDinero(d), currency }))
}

/** Totals as people read them: R$ 10,00 · US$ 5,00. */
export function formatTotals(totals: Money[]): string {
  return totals.length === 0 ? formatMoney({ amount: "0" }) : totals.map((m) => formatMoney(m)).join(" · ")
}

/** How the locale writes an amount of a currency: its separators, and what comes before and after. */
function shapeOf(code: string) {
  const parts = new Intl.NumberFormat(locale, { style: "currency", currency: code }).formatToParts(-1234.5)
  const at = (type: string) => parts.find((p) => p.type === type)?.value
  const first = parts.findIndex((p) => p.type === "integer")
  const last = parts.findLastIndex((p) => p.type === "fraction" || p.type === "integer")
  const around = (ps: Intl.NumberFormatPart[]) =>
    ps
      .filter((p) => p.type !== "minusSign")
      .map((p) => p.value)
      .join("")
  return {
    group: at("group") ?? ",",
    decimal: at("decimal") ?? ".",
    prefix: around(parts.slice(0, first)),
    suffix: around(parts.slice(last + 1)),
  }
}

/**
 * A field for an amount: typed as the locale writes it, with the currency's
 * symbol, its value the amount as text ("1234.56") and its currency.
 */
export function MoneyInput({
  id,
  value,
  onChange,
  invalid,
  negative = false,
  className,
  ...rest
}: {
  id?: string
  value: unknown
  onChange: (v: Money | null) => void
  invalid?: boolean
  /** Whether a negative amount may be typed. */
  negative?: boolean
  className?: string
  autoFocus?: boolean
  disabled?: boolean
  onBlur?: () => void
  onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
  "aria-label"?: string
  placeholder?: string
}) {
  const m = isMoney(value) ? value : null
  const code = currencyOf(m)
  const shape = shapeOf(code)
  // An amount finer than its currency keeps its places while edited.
  const scale = Math.max(places(code), Math.min(m ? placesOf(m.amount) : 0, 4))
  return (
    <NumericFormat
      id={id}
      customInput={Input}
      className={className}
      inputMode="decimal"
      value={m?.amount ?? ""}
      valueIsNumericString
      thousandSeparator={shape.group}
      decimalSeparator={shape.decimal}
      decimalScale={scale}
      fixedDecimalScale
      prefix={shape.prefix}
      suffix={shape.suffix}
      allowNegative={negative}
      onValueChange={(v, source) => {
        if (source.source === "prop") return
        onChange(v.value === "" ? null : { amount: v.value, currency: code })
      }}
      aria-invalid={invalid}
      {...rest}
    />
  )
}
